    private static int run(String name, Runnable test) {
        try {
            test.run();
        } catch (AssertionError | RuntimeException e) {
            System.out.println("FAIL ClassyMcClassface " + name + ": " + e.getMessage());
            return 1;
        }
        System.out.println("PASS ClassyMcClassface " + name);
        return 0;
    }

